use crate::connection::{ConnectionHandle, ConnectionState};
use crate::error::Error;
use crate::logger::QueryLogger;
use crate::statement::{StatementHandle, VirtualStatement};
use crate::{SqliteArguments, SqliteQueryResult, SqliteRow};
use sqlx_core::sql_str::SqlSafeStr;
use sqlx_core::Either;

pub struct ExecuteIter<'a> {
    handle: &'a mut ConnectionHandle,
    statement: &'a mut VirtualStatement,
    logger: QueryLogger,
    args: Option<SqliteArguments>,

    /// since a `VirtualStatement` can encompass multiple actual statements,
    /// this keeps track of the number of arguments so far
    args_used: usize,

    goto_next: bool,
}

pub(crate) fn iter(
    conn: &mut ConnectionState,
    query: impl SqlSafeStr,
    args: Option<SqliteArguments>,
    persistent: bool,
) -> Result<ExecuteIter<'_>, Error> {
    let query = query.into_sql_str();
    // fetch the cached statement or allocate a new one
    let statement = conn.statements.get(query.as_str(), persistent)?;

    let logger = QueryLogger::new(query, conn.log_settings.clone());

    Ok(ExecuteIter {
        handle: &mut conn.handle,
        statement,
        logger,
        args,
        args_used: 0,
        goto_next: true,
    })
}

fn bind(
    statement: &mut StatementHandle,
    arguments: &Option<SqliteArguments>,
    offset: usize,
) -> Result<usize, Error> {
    let mut n = 0;

    if let Some(arguments) = arguments {
        n = arguments.bind(statement, offset)?;
    }

    Ok(n)
}

impl ExecuteIter<'_> {
    pub fn finish(self) -> Result<(), Error> {
        for res in self {
            let _ = res?;
        }

        Ok(())
    }
}

impl Iterator for ExecuteIter<'_> {
    type Item = Result<Either<SqliteQueryResult, SqliteRow>, Error>;

    fn next(&mut self) -> Option<Self::Item> {
        let statement = if self.goto_next {
            let statement = match self.statement.prepare_next(self.handle) {
                Ok(Some(statement)) => statement,
                Ok(None) => return None,
                Err(e) => return Some(Err(e)),
            };

            self.goto_next = false;

            // sanity check: ensure the VM is reset and the bindings are cleared
            if let Err(e) = statement.handle.reset() {
                return Some(Err(e.into()));
            }

            statement.handle.clear_bindings();

            match bind(statement.handle, &self.args, self.args_used) {
                Ok(args_used) => self.args_used += args_used,
                Err(e) => return Some(Err(e)),
            }

            statement
        } else {
            self.statement.current()?
        };

        match statement.handle.step() {
            Ok(true) => {
                self.logger.increment_rows_returned();

                Some(Ok(Either::Right(SqliteRow::current(
                    statement.handle,
                    statement.columns,
                    statement.column_names,
                ))))
            }
            Ok(false) => {
                let last_insert_rowid = self.handle.last_insert_rowid();

                // `sqlite3_changes()` returns the row count for the most recently completed
                // INSERT/UPDATE/DELETE on the connection, not necessarily this statement.
                // For read-only statements (SELECT, BEGIN, COMMIT, etc.) we must report 0.
                // See https://sqlite.org/c3ref/changes.html
                let changes = if statement.handle.read_only() {
                    0
                } else {
                    statement.handle.changes()
                };
                self.logger.increase_rows_affected(changes);

                let done = SqliteQueryResult {
                    changes,
                    last_insert_rowid,
                };

                self.goto_next = true;

                Some(Ok(Either::Left(done)))
            }
            Err(e) => Some(Err(e.into())),
        }
    }
}

impl Drop for ExecuteIter<'_> {
    fn drop(&mut self) {
        self.statement.reset().ok();
    }
}

    pub fn remove_rollback_hook(&mut self) {
        self.guard.remove_rollback_hook();
    }

    pub fn last_error(&mut self) -> Option<SqliteError> {
        self.guard.handle.last_error()
    }
}

impl Drop for ConnectionState {
    fn drop(&mut self) {
        // explicitly drop statements before the connection handle is dropped
        self.statements.clear();
        self.remove_progress_handler();
        self.remove_update_hook();
        self.remove_commit_hook();
        self.remove_rollback_hook();
    }
}

impl Statements {
    fn new(capacity: usize) -> Self {
        Statements {
            cached: StatementCache::new(capacity),
            temp: None,
        }
    }

    fn get(&mut self, query: &str, persistent: bool) -> Result<&mut VirtualStatement, Error> {
        if !persistent || !self.cached.is_enabled() {
            return Ok(self.temp.insert(VirtualStatement::new(query, false)?));
        }

        let exists = self.cached.contains_key(query);

        if !exists {
            let statement = VirtualStatement::new(query, true)?;
            self.cached.insert(query, statement);
        }

        let statement = self.cached.get_mut(query).unwrap();

        if exists {
            // as this statement has been executed before, we reset before continuing
            statement.reset()?;
        }

        Ok(statement)
    }

    fn len(&self) -> usize {
        self.cached.len()
    }

    fn clear(&mut self) {
        self.cached.clear();
        self.temp = None;
    }
}
//! Times executing one large multi-statement SQL string against an in-memory SQLite database.
//!
//! ```text
//! cargo run --release --example multi_stmt_bench --features sqlite,runtime-tokio
//! cargo run --release --example multi_stmt_bench --features sqlite,runtime-tokio -- 1000 10000 50000
//! ```
//!
//! Arguments are statement counts (default: 1000 4000 16000 32000). Each count runs against a
//! fresh database; the time covers only the `raw_sql(..).execute(..)` call.

use std::time::Instant;

use sqlx::{AssertSqlSafe, Connection, SqliteConnection};

const SCHEMA: &str = "CREATE TABLE posts (id INTEGER PRIMARY KEY, title TEXT NOT NULL, body TEXT, views INTEGER NOT NULL DEFAULT 0);
CREATE TABLE tags (post_id INTEGER NOT NULL, tag TEXT NOT NULL);";

fn script(statements: usize) -> String {
    let mut sql = String::new();
    let mut posts = 0;
    for i in 0..statements {
        match i % 10 {
            0..=5 => {
                posts += 1;
                sql.push_str(&format!(
                    "INSERT INTO posts (title, body) VALUES ('Post #{posts}', 'Body of post {posts}. It''s a fairly ordinary body with some filler text in it.');\n"
                ));
            }
            6 | 7 => sql.push_str(&format!(
                "UPDATE posts SET views = views + {} WHERE id = {};\n",
                i % 7 + 1,
                i % posts + 1
            )),
            8 => sql.push_str(&format!(
                "INSERT INTO tags (post_id, tag) VALUES ({posts}, 'tag-{}');\n",
                i % 13
            )),
            _ => sql.push_str(&format!("-- checkpoint {i}\nDELETE FROM tags WHERE post_id = {};\n", i % posts)),
        }
    }
    sql
}

#[tokio::main]
async fn main() -> Result<(), sqlx::Error> {
    let counts: Vec<usize> = std::env::args()
        .skip(1)
        .map(|a| a.parse().expect("statement count"))
        .collect();
    let counts = if counts.is_empty() { vec![1000, 4000, 16000, 32000] } else { counts };

    for n in counts {
        let sql = script(n);
        let mut conn = SqliteConnection::connect("sqlite::memory:").await?;
        sqlx::raw_sql(SCHEMA).execute(&mut conn).await?;

        let start = Instant::now();
        sqlx::raw_sql(AssertSqlSafe(sql.as_str())).execute(&mut conn).await?;
        let elapsed = start.elapsed();

        let (rows,): (i64,) = sqlx::query_as("SELECT count(*) FROM posts").fetch_one(&mut conn).await?;
        println!(
            "{n:>7} statements ({:>5} KiB): {:>10.1?}  ({:.2} us/statement, {rows} posts)",
            sql.len() / 1024,
            elapsed,
            elapsed.as_secs_f64() * 1e6 / n as f64,
        );
    }
    Ok(())
}

